// Citizen contract only; Intake keeps its native texte/image/audio/video API.
const item=$input.first(), b=item.json.body, errors=[];
const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const body=object(b)?b:{};
const report_id=typeof body.report_id==='string'?body.report_id.trim():'';
const description=typeof body.description==='string'?body.description:'';
if(!/^[A-Za-z0-9_-]{3,64}$/.test(report_id))errors.push('INVALID_REPORT_ID');
if((body.description!==undefined&&typeof body.description!=='string')||description.length>3000)errors.push('INVALID_DESCRIPTION');
if(Object.keys(body).some(k=>!['report_id','description','location'].includes(k)))errors.push('UNSUPPORTED_FORM_FIELD');
let location=null;
if(body.location!==undefined&&body.location!==''){
  try{
    location=typeof body.location==='string'?JSON.parse(body.location):body.location;
    if(location!==null){
      if(!object(location)||Object.keys(location).some(k=>!['address','latitude','longitude','commune'].includes(k)))throw Error();
      for(const [key,limit] of [['latitude',90],['longitude',180]]){
        const v=location[key];if(v!==undefined&&v!==null&&(typeof v!=='number'||!Number.isFinite(v)||Math.abs(v)>limit))throw Error();
      }
      if(location.address!==undefined&&location.address!==null&&(typeof location.address!=='string'||location.address.length>300))throw Error();
      if(location.commune!==undefined&&location.commune!==null&&(typeof location.commune!=='string'||!/^COMMUNE_[A-Z0-9_]{2,31}$/.test(location.commune)))throw Error();
    }
  }catch{errors.push('INVALID_LOCATION');location=null;}
}
const files={...(item.binary||{})};
// Preserve the previous single-image alias, but never infer audio/video from it.
const keys=Object.keys(files);
if(keys.length===1&&!['image','audio','video'].includes(keys[0])&&['image/jpeg','image/png','image/webp'].includes(files[keys[0]]?.mimeType)){
  files.image=files[keys[0]];delete files[keys[0]];
}
if(Object.keys(files).some(k=>!['image','audio','video'].includes(k)))errors.push('UNSUPPORTED_OR_DUPLICATE_MEDIA_FIELD');
const image=Boolean(files.image),audio=Boolean(files.audio),video=Boolean(files.video);
if((video&&(image||audio))||(!video&&!image))errors.push('UNSUPPORTED_MEDIA_COMBINATION');
if(image&&!audio&&description.trim().length<5)errors.push('DESCRIPTION_OR_AUDIO_REQUIRED');
const mime={image:['image/jpeg','image/png','image/webp'],
  audio:['audio/wav','audio/x-wav','audio/wave','audio/mpeg','audio/mp3','audio/mp4','audio/x-m4a','audio/ogg','audio/webm','audio/flac','audio/x-flac'],
  video:['video/mp4','video/webm','video/quicktime','video/x-msvideo','video/x-matroska']};
for(const kind of ['image','audio','video'])if(files[kind]&&!mime[kind].includes(files[kind].mimeType))errors.push('UNSUPPORTED_'+kind.toUpperCase()+'_TYPE');
const mode=video?'video':audio?'image_audio':'image_text';
const decision=errors.length?'REJECT':'PASS';
const x={report_id:report_id||null,original:{description,location},submission:{mode,has_audio:audio,has_video:video},decision,
  errors:[...new Set(errors)],review_reasons:[],policy:{gate_1:{decision:'NOT_RUN',reason_codes:[]}},
  integration:{"trusted_safe_root": "C:/Municipal/MunicipaliteAuto/.runtime/intake/safe", "privacy_invariant": "checked_yunet_output_v1", "yunet_model_sha256": "8f2383e4dd3cfbb4553ea8718107fc0423210dc964f9f4280604804ed2552fa4", "local_source_sha256": "858b81f63bc4f1e17ca80b970185cb668e46be0e4317ef1735df7bc87ba56836"},
  components:{intake:{execution:'not_called',inference:'not_verified'},vision:{execution:'not_called'},knowledge:{execution:'not_called'},persistence:{execution:'not_called'}},
  trace:[{at:new Date().toISOString(),stage:'INPUT_CHECK',decision,reason_codes:[...new Set(errors)]}]};
return [{json:x,...(!errors.length?{binary:files}:{})}];

// Preparation evidence only; never classify the incident in Intake/Gate 1.
const x=$input.first().json,r=x.intake_native,http=x.intake_http||{},reasons=[];
const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const meaningful=v=>typeof v==='string'&&v.trim().length>0;
const strings=v=>Array.isArray(v)&&v.every(s=>typeof s==='string');
const hash=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
const video=x.submission?.mode==='video',audio=x.submission?.has_audio===true;
let decision='REVIEW';
if(http.transport_error)reasons.push(http.transport_error==='TIMEOUT'?'INTAKE_TIMEOUT':'INTAKE_UNAVAILABLE');
else if([400,413,415,422].includes(http.status_code)){decision='REJECT';reasons.push('INTAKE_INPUT_REJECTED');}
else if(http.status_code!==200)reasons.push('INTAKE_HTTP_FAILED');
else if(!object(r))reasons.push('INTAKE_INVALID_JSON');
else{
  const fields=['schema_version','language','cleaned_text','text_quality','transcription_audio','transcription_video','media','preparation_status','processing_errors','avertissements'];
  if(r.schema_version!=='intake-preparation-v1'||fields.some(k=>!(k in r))||Object.keys(r).some(k=>!fields.includes(k))||
    !['READY','REVIEW'].includes(r.preparation_status)||!strings(r.processing_errors)||!strings(r.avertissements)||
    typeof r.transcription_audio!=='string'||typeof r.transcription_video!=='string'||!['CLEAR','VAGUE','EMPTY'].includes(r.text_quality))reasons.push('INTAKE_PREPARATION_SCHEMA_INVALID');
  if(r.preparation_status!=='READY'||!strings(r.processing_errors)||r.processing_errors.length)reasons.push('INTAKE_PREPARATION_INCOMPLETE');
  if(r.text_quality!=='CLEAR'||!meaningful(r.cleaned_text)||!['fr','en','ar','mixed'].includes(r.language))reasons.push('INTAKE_TEXT_INCOMPLETE');
  if(audio&&!meaningful(r.transcription_audio))reasons.push('INTAKE_AUDIO_TRANSCRIPT_REQUIRED');
  if((!audio&&r.transcription_audio!=='')||(!video&&r.transcription_video!==''))reasons.push('INTAKE_UNEXPECTED_TRANSCRIPT');
  if(strings(r.avertissements)&&r.avertissements.some(w=>!/^Données masquées \(\d+ email\(s\), \d+ téléphone\(s\)\)\.$/.test(w)))reasons.push('INTAKE_PROCESSING_WARNING');
  const root=(x.integration.trusted_safe_root||'').replace(/\\/g,'/').replace(/\/$/,'');
  const expected=video?3:1,media=r.media;
  if(!Array.isArray(media)||media.length!==expected)reasons.push('INTAKE_PREPARED_MEDIA_REQUIRED');
  if(Array.isArray(media)){
    const paths=new Set();let requestDirectory=null;
    for(const [index,m] of media.entries()){
      const p=object(m)&&m.face_processing;
      const path=object(m)&&typeof m.path==='string'?m.path.replace(/\\/g,'/'):'';
      if(!object(m)||m.id!==(video?'image_video_'+(index+1):'image_independante')||m.source!==(video?'video':'image'))reasons.push('INTAKE_PREPARED_MEDIA_REQUIRED');
      if(x.integration.privacy_invariant!=='checked_yunet_output_v1'||!root||!path.startsWith(root+'/')||
        !/^[a-f0-9]{32}\/image_[a-f0-9]{32}\.png$/.test(path.slice(root.length+1))||
        !object(p)||p.detector!=='YuNet'||p.detector_completed!==true||p.write_and_decode_verified!==true||
        !Number.isInteger(p.faces_detected)||p.faces_detected<0||!hash(m.sha256)||p.sha256!==m.sha256||
        !hash(p.model_sha256)||!hash(x.integration.yunet_model_sha256)||p.model_sha256!==x.integration.yunet_model_sha256)reasons.push('PRIVACY_PROCESSING_UNVERIFIED');
      const directory=path.slice(root.length+1).split('/')[0];
      if(paths.has(path)||(requestDirectory!==null&&directory!==requestDirectory))reasons.push('INTAKE_MEDIA_ASSOCIATION_INVALID');
      paths.add(path);requestDirectory=directory;
    }
  }
  // A silent video may have no transcript. Intake must still provide usable text.
  if(!reasons.length)decision='PASS';
}
const unique=[...new Set(reasons)];
x.policy.gate_1={decision,reason_codes:unique,checks:{scope:'Text, speech and required visual preparation only',
  privacy_scope:'Checked local face-processing evidence; not complete PII anonymization',native_response_preserved:object(r)}};
x.decision=decision;
if(decision==='REJECT')x.errors.push(...unique);else x.review_reasons.push(...unique);
x.trace.push({at:new Date().toISOString(),stage:'GATE_1_PREPARATION',decision,reason_codes:unique});
const provenance=x.components.intake.service_reported_provenance;
const extraReasons=[];
if(x.components.intake.provenance_status==='invalid')extraReasons.push('INTAKE_PROVENANCE_INVALID');
if(provenance?.text_provider==='nvidia'){
  if(provenance.normalization!=='French')extraReasons.push('INTAKE_NORMALIZATION_MISMATCH');
  if(!provenance.calls.some(c=>c.stage==='text'&&c.status==='SUCCESS'))extraReasons.push('INTAKE_TEXT_INFERENCE_UNCONFIRMED');
  if(provenance.calls.some(c=>c.inference_mode==='TEST_DOUBLE'))extraReasons.push('INTAKE_TEST_DOUBLE_NOT_REAL_INFERENCE');
  if(x.submission&&provenance.transcription_provider==='nvidia'){
    const expected=x.submission.has_audio===true||(x.submission.mode==='video'&&typeof r?.transcription_video==='string'&&r.transcription_video.trim())?1:0;
    const speech=provenance.calls.filter(c=>c.stage==='transcription'&&c.status==='SUCCESS').length;
    if(speech!==expected)extraReasons.push('INTAKE_SPEECH_INFERENCE_UNCONFIRMED');
  }
}
if(extraReasons.length){
  x.policy.gate_1.reason_codes.push(...extraReasons);x.review_reasons.push(...extraReasons);
  if(x.decision!=='REJECT'){x.decision='REVIEW';x.policy.gate_1.decision='REVIEW';}
  x.trace.push({at:new Date().toISOString(),stage:'INTAKE_PROVIDER_CHECK',decision:x.policy.gate_1.decision,reason_codes:extraReasons});
}
return [{json:x}];

// Native Vision schema; no invented uncertainty boolean, agent version or scores.
const x=$input.first().json, v=x.vision_native, http=x.vision_http||{}, problems=[];
const object=o=>o!==null&&typeof o==='object'&&!Array.isArray(o);
const meaningful=s=>typeof s==='string'&&s.trim().length>0;
const accepted=['ROAD_DAMAGE','STREET_LIGHTING','WASTE','WATER_LEAK'];
const fields=['category','severity','description','evidence','text_image_consistent','confidence','uncertainty_reason','report_id','run_id'];
if(http.transport_error)problems.push(http.transport_error==='TIMEOUT'?'VISION_TIMEOUT':'VISION_UNAVAILABLE');
else if(http.status_code!==200)problems.push('VISION_HTTP_FAILED');
else if(!object(v))problems.push('VISION_INVALID_JSON');
else {
  if(fields.some(k=>!(k in v))||Object.keys(v).some(k=>!fields.includes(k)))problems.push('VISION_SCHEMA_INVALID');
  if(v.report_id!==x.report_id)problems.push('VISION_REPORT_ID_MISMATCH');
  const digest=x.media_transfer?.sha256;
  if(!meaningful(v.run_id)||typeof digest!=='string'||!v.run_id.endsWith('_UPLOAD-'+digest.slice(0,12)))problems.push('VISION_RUN_MEDIA_MISMATCH');
  if(!accepted.includes(v.category))problems.push('VISION_CATEGORY_UNSUPPORTED_OR_UNCLEAR');
  if(!['LOW','MEDIUM','HIGH'].includes(v.severity))problems.push('VISION_SEVERITY_UNCLEAR');
  if(!meaningful(v.description)||v.description.length>600)problems.push('VISION_DESCRIPTION_INVALID');
  if(!Array.isArray(v.evidence)||v.evidence.length===0||v.evidence.length>6||!v.evidence.every(meaningful))problems.push('VISION_EVIDENCE_MISSING');
  if(v.text_image_consistent!==true)problems.push('IMAGE_TEXT_MISMATCH_OR_UNCLEAR');
  if(v.uncertainty_reason!==null)problems.push('VISION_UNCERTAINTY_REQUIRES_REVIEW');
  if(typeof v.confidence!=='number'||!Number.isFinite(v.confidence)||v.confidence<0||v.confidence>1)problems.push('VISION_CONFIDENCE_MISSING_OR_INVALID');
  // No confidence cutoff: the model estimate is uncalibrated, not correctness evidence.
  if(x.media_transfer?.verified!==true)problems.push('VISION_MEDIA_NOT_VERIFIED');
}
x.decision=problems.length?'REVIEW':'PASS';x.review_reasons.push(...problems);
x.policy.gate_2={decision:x.decision,reason_codes:problems,checks:{scope:'Native visual evidence and text consistency',confidence_scope:'Uncalibrated model estimate; no numerical acceptance threshold',native_response_preserved:object(v)}};
x.trace.push({at:new Date().toISOString(),stage:'GATE_2_VISION',media_id:x.current_media?.id||null,decision:x.decision,reason_codes:problems});

// Appended to the unchanged native Gate 2 checks. REVIEW remains REVIEW.
const gate=x.policy.gate_2;
const onlyUncertainty=gate.reason_codes.length>0&&gate.reason_codes.every(r=>r==='VISION_UNCERTAINTY_REQUIRES_REVIEW');
const validUncertainty=typeof x.vision_native?.uncertainty_reason==='string'&&x.vision_native.uncertainty_reason.trim().length>0;
gate.checks.usable_for_routing_and_retrieval=gate.decision==='PASS'||(onlyUncertainty&&validUncertainty);
gate.checks.continuation_policy='Continue valid, consistent classifications; retain uncertainty for ticket review.';
if(gate.decision==='REVIEW'&&gate.checks.usable_for_routing_and_retrieval){
  x.trace.push({at:new Date().toISOString(),stage:'REVIEW_CONTINUATION',decision:'CONTINUE_WITH_REVIEW',reason_codes:gate.reason_codes});
}
return [{json:x}];

// Rules control the department: no LLM is permitted to choose it.
const x=$input.first().json;
const departments={
  ROAD_DAMAGE:'ROADS_DEPARTMENT',
  STREET_LIGHTING:'PUBLIC_LIGHTING_DEPARTMENT',
  WASTE:'SANITATION_DEPARTMENT',
  WATER_LEAK:'WATER_SERVICES_DEPARTMENT'
};
x.department=departments[x.vision.category]||null;
if(!x.department){x.decision='REVIEW';x.review_reasons.push('NO_DEPARTMENT_RULE');}
// Executing organisation for the staff console; no LLM chooses it either.
// SUPERVISING_COMMUNE is resolved by the database to the citizen's commune.
x.organisation={ROAD_DAMAGE:'SUPERVISING_COMMUNE',WASTE:'SUPERVISING_COMMUNE',STREET_LIGHTING:'STEG',WATER_LEAK:'SONEDE'}[x.vision.category]||null;
x.trace.push({at:new Date().toISOString(),stage:'DEPARTMENT_ROUTING',decision:x.decision,reason_codes:x.department?[]:['NO_DEPARTMENT_RULE']});
return [{json:x}];

// Deterministic source/context checks. Scores are retrieval similarities, not truth probabilities.
const x=$input.first().json,k=x.knowledge_native,http=x.knowledge_http||{},e=x.knowledge_evidence,reasons=[];
const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
const meaningful=v=>typeof v==='string'&&v.trim().length>0;
if(http.transport_error)reasons.push(http.transport_error==='TIMEOUT'?'KNOWLEDGE_TIMEOUT':'KNOWLEDGE_UNAVAILABLE');
else if(http.status_code!==200)reasons.push(http.status_code===503?'KNOWLEDGE_NOT_READY_OR_BUSY':http.status_code===422?'KNOWLEDGE_CONTRACT_REJECTED':'KNOWLEDGE_HTTP_FAILED');
else if(!object(k))reasons.push('KNOWLEDGE_INVALID_JSON');
else{
  const fields=['procedure','deadline','answer_found','sources'];
  if(fields.some(f=>!(f in k))||Object.keys(k).some(f=>!fields.includes(f))||typeof k.answer_found!=='boolean'||
    (k.procedure!==null&&!meaningful(k.procedure))||(k.deadline!==null&&!meaningful(k.deadline))||!Array.isArray(k.sources))reasons.push('KNOWLEDGE_NATIVE_SCHEMA_INVALID');
  if(k.answer_found!==true){
    reasons.push('KNOWLEDGE_NO_SUPPORTED_ANSWER');
    if(k.procedure!==null||k.deadline!==null||(Array.isArray(k.sources)&&k.sources.length))reasons.push('KNOWLEDGE_REFUSAL_INCONSISTENT');
  }else{
    if(!meaningful(k.procedure)||k.procedure.length>8000||['null','none'].includes(k.procedure.trim().toLowerCase()))reasons.push('KNOWLEDGE_PROCEDURE_INVALID');
    if(!Array.isArray(k.sources)||k.sources.length<1||k.sources.length>3)reasons.push('KNOWLEDGE_SOURCES_REQUIRED');
    if(Array.isArray(k.sources)){
      const ids=new Set();
      for(const s of k.sources){
        if(!object(s)||Object.keys(s).sort().join(',')!=='chunk_id,score,url'||!/^DOC-[A-Z]+-\d{2}#\d{2}$/.test(s.chunk_id||'')||
          typeof s.url!=='string'||!s.url.startsWith('https://')||typeof s.score!=='number'||!Number.isFinite(s.score)||s.score<.4||s.score>1||ids.has(s.chunk_id))reasons.push('KNOWLEDGE_SOURCE_INVALID');
        ids.add(s?.chunk_id);
      }
    }
    // The delivered ledger certifies no service response/repair commitment.
    if(k.deadline!==null)reasons.push('KNOWLEDGE_DEADLINE_REQUIRES_REVIEW');
  }
  if(!object(e)||e.receipt_verified!==true||e.request_response_match!==true||e.indexed_context_verified!==true||e.sources_match_selected_context!==true||e.source_count!==k.sources?.length)
    reasons.push('KNOWLEDGE_EVIDENCE_UNVERIFIED');
  else if(k.answer_found===true){
    if(e.provider!=='ollama'||e.generation_model!=='qwen2.5:3b'||!['bge-m3','bge-m3:latest'].includes(e.embedding_model)||!/^[a-f0-9]{64}$/.test(e.embedding_digest||'')||e.generation_recorded!==true)
      reasons.push('KNOWLEDGE_EXECUTION_UNVERIFIED');
    if(e.procedure_verbatim_in_context!==true)reasons.push('KNOWLEDGE_PARAPHRASE_REQUIRES_REVIEW');
  }
}
const unique=[...new Set(reasons)];x.decision=unique.length?'REVIEW':'PASS';x.review_reasons.push(...unique);
x.policy.gate_3={decision:x.decision,reason_codes:unique,checks:{scope:'Native schema, actual indexed source context and conservative verbatim procedure support',
  municipality:'Commune de Tunis',incident_location_inferred:false,semantic_limit:'No guarantee of semantic applicability, source currentness or real-world correctness',
  native_response_preserved:object(k),receipt_verified:object(e)&&e.receipt_verified===true}};
if(object(e)&&e.receipt_verified===true)x.components.knowledge={...x.components.knowledge,
  inference:e.generation_recorded?'native_generation_recorded':'no_generation_recorded',retrieval:'indexed_context_verified',
  configured_provider:e.provider,configured_generation_model:e.generation_model,embedding_model:e.embedding_model};
x.trace.push({at:new Date().toISOString(),stage:'GATE_3_KNOWLEDGE',decision:x.decision,reason_codes:unique});
return [{json:x}];

const x=$input.first().json;
x.ticket={
  ticket_id:'DEMO-TKT-'+x.report_id,
  report_id:x.report_id,status:'TICKET_CREATED',
  category:x.vision.category,severity:x.vision.severity,
